@push('script')<script>(()=>{const search=document.getElementById('checklist-search'),entries=[...document.querySelectorAll('.checklist-entry')];let filter='ALL';const refresh=()=>{const term=search.value.toLowerCase();entries.forEach(row=>row.classList.toggle('d-none',(filter!=='ALL'&&row.dataset.status!==filter)||!row.dataset.search.includes(term)));document.querySelectorAll('.checklist-section').forEach(section=>section.classList.toggle('d-none',!section.querySelector('.checklist-entry:not(.d-none)')))};search?.addEventListener('input',refresh);document.querySelectorAll('.checklist-filter').forEach(btn=>btn.addEventListener('click',()=>{filter=btn.dataset.filter;document.querySelectorAll('.checklist-filter').forEach(b=>b.classList.toggle('active',b===btn));refresh()}));document.querySelectorAll('.qc-choice').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.entry,status=button.dataset.value,row=button.closest('.checklist-entry'),select=document.getElementById('status-'+id);select.value=status;row.dataset.status=status;row.classList.toggle('is-issue',status==='ISSUE');row.classList.toggle('is-ok',status==='OK');row.querySelectorAll('.qc-choice').forEach(choice=>choice.classList.toggle('active',choice===button));document.getElementById('obs-'+id).classList.toggle('d-none',status!=='ISSUE');const checked=entries.filter(item=>item.dataset.status!=='PENDING').length;document.getElementById('qc-checked').textContent=checked;document.getElementById('qc-progress').style.width=Math.round(checked/entries.length*100)+'%'}))})();</script>@endpush
